create table admin_role_user (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, admin_role_id uuid not null, user_id uuid not null, primary key (id));
create table admin_roles (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, name varchar(50) not null unique, primary key (id));
create table appointments (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, note varchar(255), requested_slot timestamp(6) with time zone not null, status varchar(20) not null check (status in ('PENDING','ACCEPTED','REJECTED','COMPLETED','CANCELLED')), customer_id uuid not null, owner_id uuid not null, property_id uuid not null, primary key (id));
create table audit_logs (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, action varchar(100) not null, ip_address varchar(45), reason varchar(255), target_id uuid, target_type varchar(50), admin_id uuid not null, primary key (id));
create table broadcast_deliveries (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, clicked boolean not null, opened boolean not null, opened_at timestamp(6) with time zone, broadcast_id uuid not null, user_id uuid not null, primary key (id));
create table broadcasts (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, body TEXT, title varchar(255) not null, type varchar(20) not null check (type in ('NEW_PROPERTY','OFFER','DISCOUNT','VIDEO','NEWS')), company_id uuid not null, primary key (id));
create table cities (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, is_active boolean not null, name varchar(100) not null, name_ar varchar(100) not null, primary key (id));
create table cms_pages (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, body_html TEXT, locale varchar(10), slug varchar(100) not null unique, title varchar(255) not null, primary key (id));
create table companies (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, cover_url varchar(255), coverage_area JSONB, description TEXT, description_ar TEXT, email varchar(150), followers_count integer not null, logo_url varchar(255), name varchar(200) not null, name_ar varchar(200), phone varchar(20), plan varchar(20) not null check (plan in ('BASIC','PREMIUM','ENTERPRISE')), reputation_score numeric(3,2) not null, type varchar(30) not null check (type in ('REAL_ESTATE_OFFICE','FINISHING_COMPANY','MAINTENANCE_PROVIDER')), verified boolean not null, website varchar(150), whatsapp varchar(20), owner_id uuid not null, primary key (id));
create table company_portfolio (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, after_url varchar(255), before_url varchar(255), caption varchar(255), project_date date, company_id uuid not null, primary key (id));
create table company_services (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, company_id uuid not null, service_id uuid not null, primary key (id), unique (company_id, service_id));
create table company_staff (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, role varchar(50), company_id uuid not null, user_id uuid not null, primary key (id));
create table conversations (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, last_message_preview varchar(255), last_seen_user_one uuid, last_seen_user_two uuid, user_one_id uuid not null, user_two_id uuid not null, primary key (id), constraint uq_conversation_user_pair unique (user_one_id, user_two_id));
create table coupons (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, code varchar(50) not null unique, discount_percent smallint not null, max_uses integer, valid_from date not null, valid_to date not null, primary key (id));
create table districts (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, name varchar(100) not null, name_ar varchar(100) not null, city_id uuid not null, primary key (id));
create table feature_flags (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, is_enabled boolean not null, key_name varchar(100) not null unique, rollout_scope JSONB, primary key (id));
create table features (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, icon varchar(50), name varchar(100) not null, name_ar varchar(100) not null, name_en varchar(100), primary key (id));
create table follower_preferences (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, wants_discounts boolean not null, wants_new_properties boolean not null, wants_news boolean not null, wants_offers boolean not null, wants_videos boolean not null, company_id uuid not null, user_id uuid not null, primary key (id), unique (user_id, company_id));
create table followers (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, company_id uuid not null, user_id uuid not null, primary key (id), unique (user_id, company_id));
create table fraud_flags (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, entity_id uuid not null, entity_type varchar(30) not null check (entity_type in ('PROPERTY','COMPANY','TECHNICIAN','SERVICE_PROVIDER')), flag_type varchar(30) not null check (flag_type in ('DUPLICATE_LISTING','FAKE_REVIEW','SPAM_MESSAGE','ABNORMAL_FOLLOW_ACTIVITY')), status varchar(20) not null, primary key (id));
create table messages (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, media_url varchar(255), payload JSONB, text_body TEXT, type varchar(20) not null check (type in ('TEXT','IMAGE','LOCATION','VOICE','PDF','PROPERTY_CARD','APPOINTMENT_CARD')), conversation_id uuid not null, sender_id uuid not null, primary key (id));
create table notifications (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, body TEXT, entity_id uuid, entity_type varchar(30) check (entity_type in ('PROPERTY','COMPANY','TECHNICIAN','SERVICE_PROVIDER')), is_read boolean not null, title varchar(255) not null, type varchar(20) not null check (type in ('SYSTEM','MARKETING','PERSONAL','SMART')), user_id uuid not null, primary key (id));
create table otp_codes (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, attempts integer not null, code_hash varchar(64) not null, email varchar(150), expires_at timestamp(6) with time zone not null, invalidated boolean not null, phone varchar(20), purpose varchar(30) not null check (purpose in ('REGISTRATION','LOGIN','PASSWORD_RESET')), verified boolean not null, primary key (id));
create table payments (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, amount numeric(12,2) not null, gateway_reference varchar(150), method varchar(50), status varchar(20) not null check (status in ('PENDING','PAID','FAILED','REFUNDED')), subscription_id uuid not null, primary key (id));
create table properties (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, category varchar(30) not null, description TEXT, description_ar TEXT, features JSONB DEFAULT '{}', finishing_level varchar(20) check (finishing_level in ('UNFINISHED','SEMI_FINISHED','FINISHED','LUXURY')), hide_reason varchar(30) check (hide_reason in ('INAPPROPRIATE_PHOTOS','INCORRECT_DATA','DUPLICATE','FRAUD','ALREADY_SOLD')), is_featured boolean not null, latitude numeric(10,7), longitude numeric(10,7), price numeric(12,2) not null, purpose varchar(10) not null check (purpose in ('SALE','RENT')), readiness varchar(20) not null check (readiness in ('READY','UNDER_CONSTRUCTION')), status varchar(20) not null check (status in ('DRAFT','PENDING_REVIEW','PUBLISHED','HIDDEN','SOLD','RENTED','ARCHIVED')), street varchar(200), title varchar(200) not null, title_ar varchar(200), city_id uuid not null, district_id uuid not null, owner_id uuid not null, primary key (id));
create table property_images (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, sort_order integer not null, url varchar(255) not null, property_id uuid not null, primary key (id));
create table property_videos (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, duration_seconds integer, thumbnail_url varchar(255), video_url varchar(255) not null, property_id uuid not null, primary key (id));
create table reports (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, decision TEXT, entity_id uuid not null, entity_type varchar(30) not null check (entity_type in ('PROPERTY','COMPANY','TECHNICIAN','SERVICE_PROVIDER')), evidence_urls JSONB, reason varchar(255) not null, status varchar(20) not null check (status in ('OPEN','REVIEWING','RESOLVED','DISMISSED')), assigned_staff_id uuid, reporter_id uuid not null, primary key (id));
create table reviews (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, comment TEXT, entity_id uuid not null, entity_type varchar(30) not null check (entity_type in ('PROPERTY','COMPANY','TECHNICIAN','SERVICE_PROVIDER')), images JSONB, interaction_verified boolean not null, rating smallint not null, source_appointment_id uuid, video_url varchar(255), reviewer_id uuid not null, primary key (id));
create table saved_items (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, entity_id uuid not null, entity_type varchar(30) not null check (entity_type in ('PROPERTY','COMPANY','TECHNICIAN','SERVICE_PROVIDER')), user_id uuid not null, primary key (id), unique (user_id, entity_type, entity_id));
create table services (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, category varchar(50) not null, icon_url varchar(500), name varchar(100) not null, name_ar varchar(150) not null, name_en varchar(150), primary key (id));
create table subscription_plans (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, broadcast_quota integer not null, is_active boolean not null, listing_quota integer not null, name varchar(100) not null, name_ar varchar(100) not null, name_en varchar(100), price numeric(10,2) not null, tier varchar(50) not null check (tier in ('BASIC','PREMIUM','ENTERPRISE')), primary key (id));
create table subscriptions (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, company_id uuid, end_date date not null, start_date date not null, status varchar(20) not null check (status in ('ACTIVE','EXPIRED','CANCELLED')), user_id uuid, plan_id uuid not null, primary key (id));
create table users (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, email varchar(150) unique, last_login_at timestamp(6) with time zone, name varchar(120) not null, password_hash varchar(255) not null, phone varchar(20) unique, photo_url varchar(255), refresh_token_id varchar(64), role varchar(20) not null check (role in ('CUSTOMER','OWNER','OFFICE','COMPANY','TECHNICIAN','ADMIN')), status varchar(20) not null check (status in ('ACTIVE','SUSPENDED','PENDING','DELETED')), verification_level smallint not null, city_id uuid, primary key (id));
create table verifications (id uuid not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, document_url varchar(255), rejection_reason varchar(255), reviewed_at timestamp(6) with time zone, status varchar(20) not null check (status in ('PENDING','ACCEPTED','REJECTED')), type varchar(30) not null check (type in ('PHONE','EMAIL','NATIONAL_ID','COMMERCIAL_REGISTRY')), reviewed_by uuid, user_id uuid not null, primary key (id));
create index idx_otp_phone_purpose on otp_codes (phone, purpose);
create index idx_otp_email_purpose on otp_codes (email, purpose);
